// ── Helper: resolve without compounds ─────────────────────────
function resolveSimpleSV(w: string): DictEntry | null {
  if (dictionary[w]) return dictionary[w];

  // Irregular verb
  if (IRREGULAR_MAP[w]) {
    const inf = IRREGULAR_MAP[w];
    if (dictionary[inf]) return dictionary[inf];
  }

  // Definite form reversal
  for (const suf of ['erna', 'arna', 'orna', 'anden', 'andet', 'en', 'et', 'na', 'n', 't']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
      if (dictionary[base + 'a']) return dictionary[base + 'a'];
      if (dictionary[base + 'e']) return dictionary[base + 'e'];
    }
  }

  // Plural stripping
  for (const suf of ['ar', 'er', 'or', 'r']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
      if (dictionary[base + 'a']) return dictionary[base + 'a'];
      if (dictionary[base + 'e']) return dictionary[base + 'e'];
    }
  }

  // Verb form stripping
  for (const suf of ['ande', 'ende', 'ade', 'ades', 'at', 'de', 'te', 'ts', 't', 's']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
      if (dictionary[base + 'a']) return dictionary[base + 'a'];
      if (dictionary[base + 'e']) return dictionary[base + 'e'];
    }
  }

  // Adjective forms
  for (const suf of ['iga', 'igt', 'ig', 'iska', 'iskt', 'isk', 'iva', 'ivt', 'iv', 'ad', 'at', 'a', 't', 'e']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
    }
  }

  // Comparative/superlative
  for (const suf of ['aste', 'are', 'ast']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
    }
  }

  // Derivational suffixes
  for (const suf of ['ighet', 'ning', 'ling', 'else', 'het', 'skap', 'tion', 'ering']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
      if (dictionary[base + 'a']) return dictionary[base + 'a'];
      if (dictionary[base + 'e']) return dictionary[base + 'e'];
    }
  }

  // Prefix stripping
  const prefixes = ['be', 'för', 'an', 'av', 'in', 'på', 'ut', 'om', 'upp', 'sam', 'fram', 'till'];
  for (const pfx of prefixes) {
    if (w.startsWith(pfx) && w.length > pfx.length + 2) {
      const rest = w.slice(pfx.length);
      if (dictionary[rest]) return dictionary[rest];
      if (dictionary[rest + 'a']) return dictionary[rest + 'a'];
    }
  }

  return null;
}

// ── Helper: check if a Swedish word is known ──────────────────
function isKnownSV(w: string): boolean {
  if (dictionary[w]) return true;
  for (const suf of ['en', 'et', 'er', 'ar', 'or', 'a', 'e', 'n', 's', 't']) {
    if (w.endsWith(suf) && w.length > suf.length + 2 && dictionary[w.slice(0, -suf.length)]) return true;
  }
  for (const suf of ['en', 'et', 'n', 't']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base + 'a'] || dictionary[base + 'e']) return true;
    }
  }
  return false;
}

// ── Helper: compound decomposition for Swedish ────────────────
function resolveCompoundSV(w: string): DictEntry | null {
  const linkers = ['', 's', 'o', 'u', 'e', 'es', 'ar', 'er', 'nings', 'ings'];
  for (let i = 2; i <= w.length - 2; i++) {
    const left = w.slice(0, i);
    if (!isKnownSV(left)) continue;

    for (const lk of linkers) {
      if (lk && w.slice(i, i + lk.length) !== lk) continue;
      const right = w.slice(i + lk.length);
      if (right.length < 2) continue;

      const rr = resolveSimpleSV(right);
      if (rr) return rr;

      // Suffix strip on right part
      for (const suf of ['en', 'et', 'erna', 'arna', 'orna', 'na', 'ar', 'er', 'or', 'n', 'a', 't', 'ning', 'ande']) {
        if (right.endsWith(suf) && right.length > suf.length + 2) {
          const rstem = right.slice(0, -suf.length);
          if (dictionary[rstem]) return dictionary[rstem];
          if (dictionary[rstem + 'a']) return dictionary[rstem + 'a'];
          if (dictionary[rstem + 'e']) return dictionary[rstem + 'e'];
        }
      }

      // Recursive for 3-part compounds
      if (right.length >= 5) {
        const inner = resolveCompoundSV(right);
        if (inner) return inner;
      }
    }
  }
  return null;
}

export function lookupWord(raw: string): DictEntry | null {
  let clean = raw.toLowerCase().replace(/[¿¡.,!?;:"""\u2018\u2019()—–«»/]/g, '').trim();
  // Strip leading/trailing digits but keep the word (e.g., "1600-talet" -> "talet")
  clean = clean.replace(/^\d+[-–]?/, '').replace(/[-–]?\d+$/, '').trim();
  if (!clean || clean.length < 1) return null;

  // 1. Direct / inflection / verb lookup
  const simple = resolveSimpleSV(clean);
  if (simple) return simple;

  // 2. "jätte-" augmentative prefix (jättetrevligt, jättemycket, jätteroligt)
  if (clean.startsWith('jätte') && clean.length > 7) {
    const rest = clean.slice(5);
    const r = resolveSimpleSV(rest);
    if (r) return r;
  }

  // 3. Common compound prefixes
  const commonPfx = ['väl', 'ny', 'stor', 'halv', 'hel', 'hem', 'sam', 'själv', 'mång'];
  for (const pfx of commonPfx) {
    if (clean.startsWith(pfx) && clean.length > pfx.length + 2) {
      const rest = clean.slice(pfx.length);
      const r = resolveSimpleSV(rest);
      if (r) return r;
    }
  }

  // 4. Hyphenated compounds
  if (clean.includes('-')) {
    const parts = clean.split('-');
    for (let p = parts.length - 1; p >= 0; p--) {
      if (parts[p].length < 2) continue;
      const r = resolveSimpleSV(parts[p]);
      if (r) return r;
    }
    const joined = parts.join('');
    const jr = resolveSimpleSV(joined);
    if (jr) return jr;
    const jc = resolveCompoundSV(joined);
    if (jc) return jc;
  }

  // 5. Compound decomposition: strip inflections first, then try splitting
  const forms = [clean];
  for (const suf of ['en', 'et', 'erna', 'arna', 'orna', 'na', 'ar', 'er', 'or', 'n', 'a', 't', 's']) {
    if (clean.endsWith(suf) && clean.length > suf.length + 4) {
      forms.push(clean.slice(0, -suf.length));
    }
  }

  for (const form of forms) {
    if (form.length < 4) continue;
    const cr = resolveCompoundSV(form);
    if (cr) return cr;
  }

  return null;
}
